<<<<<<<< SEARCH
int emul_bmi160_get_reg_value(const struct emul *emul, unsigned int reg_addr,
			      uint8_t *val, int bytes)
{
	struct bmi160_emul_data *data =
		(struct bmi160_emul_data *)emul->data;

	for (int i = 0; i < bytes; i++) {
		val[i] = data->reg[reg_addr + i];
	}

	return 0;
}
